from taf.fdsw.rc.interfaces.FDSW18SP.security import Security18SP


class Security21D(Security18SP):
    def __init__(self, client):
        super(Security21D, self).__init__(client)

    def change_ssh_user_password(self, username, password, timeout):
        resp = self._client.send(
            method='config.utils.changeSshUserPassword',
            parameters={'username': username, 'password': password},
            timeout=timeout
        )
        return resp
